package hikyubank.application.service;
import java.util.*;import java.math.BigDecimal;import java.time.*;
import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.*;
import hikyubank.application.dto.BankingDtos.*;import hikyubank.application.dto.PaymentDtos.Lookup;
import hikyubank.application.exception.BankException;import hikyubank.application.model.Notification;
import hikyubank.dataaccess.postgresql.*;import hikyubank.dataaccess.repository.NotificationRepository;
@Service public class BankingService {
 public static final List<String> CATEGORIES=List.of("Groceries","Dining","Transport","Shopping","Subscriptions","Utilities","Housing","Health","Entertainment","Other");
 public static final List<Biller> BILLERS=List.of(new Biller("electric","Demo Electric","Utilities"),new Biller("internet","Demo Internet","Utilities"),new Biller("water","Demo Water","Utilities"),new Biller("rent","Demo Rent","Housing"));
 private final BankingRepository repo;private final ExtensionRepository store;private final AccountService accounts;private final PaymentService peers;private final SecurityService security;private final AlertService alerts;private final NotificationRepository notifications;private final Clock clock;
 public BankingService(BankingRepository repo,ExtensionRepository store,AccountService accounts,PaymentService peers,SecurityService security,AlertService alerts,NotificationRepository notifications,Clock clock){this.repo=repo;this.store=store;this.accounts=accounts;this.peers=peers;this.security=security;this.alerts=alerts;this.notifications=notifications;this.clock=clock;}
 private BankException bad(String code,String message){return new BankException(400,code,message);}
 private void basic(OperationInput p){if(p.type()==null||!List.of("purchase","repayment","bill").contains(p.type()))throw bad("INVALID_OPERATION","Choose purchase, repayment or bill payment.");if(p.sourceAccountId()==null||p.idempotencyKey()==null)throw bad("INVALID_OPERATION","Choose an account and request key.");if(p.amount()==null||p.amount().signum()<=0||p.amount().scale()>2||p.amount().compareTo(new BigDecimal("1000000"))>0)throw bad("INVALID_AMOUNT","Enter a positive amount with at most two decimal places, up to $1,000,000.");if(p.note()!=null&&p.note().length()>250)throw bad("INVALID_NOTE","Keep your note within 250 characters.");}
 private static String clean(String s){return s==null?"":s.trim();}
 public String fingerprint(OperationInput p){basic(p);var values=List.of("banking",p.type(),p.sourceAccountId().toString(),String.valueOf(p.targetAccountId()),String.valueOf(p.payeeId()),clean(p.payeeReference()),clean(p.merchant()),clean(p.category()),p.amount().setScale(2).toPlainString(),clean(p.note()),p.idempotencyKey().toString());StringBuilder out=new StringBuilder();for(String v:values)out.append(v.length()).append(':').append(v);return PaymentAuthorizationService.hash(out.toString());}
 public void validate(UUID user,OperationInput p){basic(p);var source=accounts.get(user,p.sourceAccountId());if(!"active".equals(source.status()))throw bad("ACCOUNT_NOT_ELIGIBLE","Choose an active account.");
  if("purchase".equals(p.type())){if(!List.of("checking","credit").contains(source.type()))throw bad("ACCOUNT_NOT_ELIGIBLE","Use an active Checking debit card or credit card.");if(clean(p.merchant()).isEmpty()||clean(p.merchant()).length()>100||!CATEGORIES.contains(p.category()))throw bad("INVALID_PURCHASE","Enter a merchant and choose a spending category.");if(p.targetAccountId()!=null||p.payeeId()!=null||p.payeeReference()!=null)throw bad("INVALID_PURCHASE","A purchase uses one card account.");}
  else {if(!List.of("checking","savings").contains(source.type()))throw bad("ACCOUNT_NOT_ELIGIBLE","Use an active Checking or Everyday Saving account.");if(p.merchant()!=null||p.category()!=null)throw bad("INVALID_OPERATION","Merchant/category are assigned by this payment workflow.");if("repayment".equals(p.type())){if(p.targetAccountId()==null||p.targetAccountId().equals(p.sourceAccountId())||p.payeeId()!=null||p.payeeReference()!=null)throw bad("INVALID_TARGET","Choose your own credit card account.");var target=accounts.get(user,p.targetAccountId());if(!"active".equals(target.status())||!"credit".equals(target.type()))throw bad("ACCOUNT_NOT_ELIGIBLE","Choose an active credit card.");}else{if(p.targetAccountId()!=null||p.payeeId()==null)throw bad("INVALID_PAYEE","Choose a saved bill payee.");var payee=repo.payee(user,p.payeeId());if(payee==null||!"biller".equals(payee.kind()))throw new BankException(404,"PAYEE_NOT_FOUND","Bill payee not found.");if(!payee.reference().equals(clean(p.payeeReference())))throw bad("PAYEE_CHANGED","The saved bill reference changed. Review the payee and request a new code.");}}}
 public List<OperationReceipt> history(UUID user){return repo.history(user);}
 @Transactional public OperationReceipt execute(UUID user,OperationInput p){basic(p);security.verifyPin(user,p.pin());store.lockUser(user);String hash=fingerprint(p);var prior=repo.existing(user,p.idempotencyKey());if(prior!=null){if(!hash.equals(repo.requestHash(user,p.idempotencyKey())))throw new BankException(409,"IDEMPOTENCY_CONFLICT","This request key belongs to a different financial operation.");return prior;}
  var locked=repo.lockAccounts(user,p.sourceAccountId(),p.targetAccountId());validate(user,p);var source=locked.stream().filter(a->p.sourceAccountId().equals(a.get("id"))).findFirst().orElseThrow();String type=(String)source.get("type");BigDecimal balance=(BigDecimal)source.get("balance");String merchant,category;UUID id=UUID.randomUUID();Instant now=clock.instant();
  if("purchase".equals(p.type())){if(repo.locked(user,p.sourceAccountId()))throw new BankException(409,"CARD_LOCKED","This card is locked. Unlock it before a new purchase.");if("credit".equals(type)){var limit=(BigDecimal)source.get("credit_limit");if(limit==null||balance.add(p.amount()).compareTo(limit)>0)throw new BankException(409,"CREDIT_LIMIT_EXCEEDED","This purchase exceeds the available credit limit.");}else if(balance.compareTo(p.amount())<0)throw new BankException(409,"INSUFFICIENT_FUNDS","The account has insufficient funds.");merchant=clean(p.merchant());category=p.category();}
  else {if(balance.compareTo(p.amount())<0)throw new BankException(409,"INSUFFICIENT_FUNDS","The source account has insufficient funds.");if("repayment".equals(p.type())){var target=locked.stream().filter(a->p.targetAccountId().equals(a.get("id"))).findFirst().orElseThrow();if(((BigDecimal)target.get("balance")).compareTo(p.amount())<0)throw new BankException(409,"OVERPAYMENT","The repayment exceeds the outstanding credit balance.");merchant="Credit card repayment";category="Credit payment";}else{var payee=repo.payee(user,p.payeeId());var biller=BILLERS.stream().filter(b->b.code().equals(payee.identifier())).findFirst().orElseThrow();merchant=payee.alias()+" · "+biller.name();category=biller.category();}}
  repo.operation(id,user,p,merchant,category,hash,now);
  if("purchase".equals(p.type())&&"credit".equals(type))store.adjustBalance(p.sourceAccountId(),p.amount());else store.adjustBalance(p.sourceAccountId(),p.amount().negate());
  String kind="repayment".equals(p.type())?"credit_payment":"expense";repo.leg(id,p.sourceAccountId(),merchant,category,p.amount().negate(),kind,p.note(),now);
  if("repayment".equals(p.type())){repo.reduceCredit(p.targetAccountId(),p.amount());repo.leg(id,p.targetAccountId(),"Credit repayment received",category,p.amount(),kind,p.note(),now);}
  notifications.save(user,new Notification(UUID.randomUUID(),null,p.sourceAccountId(),"Simulation completed",merchant+" · $"+p.amount()+". No real card charge or external payment was made.",now.toString(),false,false,"banking"));
  trigger(user,p.sourceAccountId(),type,id,p.amount(),now);if(p.targetAccountId()!=null)trigger(user,p.targetAccountId(),"credit",id,p.amount(),now);
  return repo.existing(user,p.idempotencyKey());
 }
 private void trigger(UUID user,UUID account,String type,UUID operation,BigDecimal amount,Instant now){var prefs=store.preferences(user);var balance=store.balance(account);for(var rule:alerts.list(user)){if(!rule.enabled()||!account.equals(rule.accountId()))continue;boolean fire=("low_balance".equals(rule.type())&&!"credit".equals(type)&&prefs.lowBalance()&&balance.compareTo(rule.amount())<0)||("large_transaction".equals(rule.type())&&prefs.largeTransaction()&&amount.compareTo(rule.amount())>=0);if(fire&&repo.claim(operation,rule.id()))notifications.save(user,new Notification(UUID.randomUUID(),rule.id(),account,rule.title(),"A successful simulated financial operation triggered this reminder. Amount: $"+amount+".",now.toString(),false,false,"banking"));}}
 public List<Payee> payees(UUID user){return repo.payees(user);}
 @Transactional public Payee savePayee(UUID user,PayeeInput p){store.lockUser(user);if(clean(p.alias()).isEmpty())throw bad("INVALID_PAYEE","Enter a payee nickname.");if("peer".equals(p.kind())){if(p.identifier()==null||!p.identifier().matches("[a-z0-9][a-z0-9._-]{2,79}"))throw bad("INVALID_RECIPIENT","Enter a lowercase Hikyu username.");peers.lookup(user,new Lookup(p.identifier()));if(!clean(p.reference()).isEmpty())throw bad("INVALID_PAYEE","Peer recipients do not use a bill reference.");}else if(!"biller".equals(p.kind())||BILLERS.stream().noneMatch(b->b.code().equals(p.identifier())))throw bad("INVALID_PAYEE","Choose a simulated biller.");else if(clean(p.reference()).isEmpty())throw bad("INVALID_PAYEE","Enter a simulation-only bill reference.");UUID id=repo.savePayee(user,p);return repo.payee(user,id);}
 @Transactional public Payee editPayee(UUID user,UUID id,PayeeEdit p){store.lockUser(user);var old=repo.payee(user,id);if(old==null)throw new BankException(404,"PAYEE_NOT_FOUND","Payee not found.");if(clean(p.alias()).isEmpty()||("biller".equals(old.kind())&&clean(p.reference()).isEmpty())||("peer".equals(old.kind())&&!clean(p.reference()).isEmpty()))throw bad("INVALID_PAYEE","Enter a nickname and, for billers, a simulation reference.");repo.editPayee(user,id,p);return repo.payee(user,id);}
 @Transactional public void deletePayee(UUID user,UUID id){store.lockUser(user);if(repo.deletePayee(user,id)!=1)throw new BankException(404,"PAYEE_NOT_FOUND","Payee not found.");}
 @Transactional public List<Card> cards(UUID user){return repo.cards(user);}
 @Transactional public Card lockCard(UUID user,UUID id,boolean locked){store.lockUser(user);var a=accounts.get(user,id);if(!List.of("checking","credit").contains(a.type())||!"active".equals(a.status()))throw bad("ACCOUNT_NOT_ELIGIBLE","Choose an active card account.");repo.ensureCards(user);repo.lockCard(user,id,locked);return repo.cards(user).stream().filter(c->c.accountId().equals(id)).findFirst().orElseThrow();}
 private LocalDate month(String value){try{var m=YearMonth.parse(value);if(m.getYear()<1970||m.getYear()>2100)throw new IllegalArgumentException();return m.atDay(1);}catch(Exception e){throw bad("INVALID_MONTH","Use a month in YYYY-MM format between 1970 and 2100.");}}
 public List<Budget> budgets(UUID user,String month){return repo.budgets(user,month(month));}
 @Transactional public Budget saveBudget(UUID user,UUID id,BudgetInput p){if(!CATEGORIES.contains(p.category())&&!"Peer transfer".equals(p.category()))throw bad("INVALID_CATEGORY","Choose a supported spending category.");if(p.limit()==null||p.limit().signum()<=0||p.limit().scale()>2)throw bad("INVALID_BUDGET","Enter a positive budget with at most two decimals.");var m=month(p.month());UUID saved=repo.saveBudget(user,id,m,p);if(saved==null)throw new BankException(404,"BUDGET_NOT_FOUND","Budget not found.");return repo.budgets(user,m).stream().filter(b->b.id().equals(saved)).findFirst().orElseThrow();}
 @Transactional public void deleteBudget(UUID user,UUID id){if(repo.deleteBudget(user,id)!=1)throw new BankException(404,"BUDGET_NOT_FOUND","Budget not found.");}
 @Transactional(readOnly=true,isolation=Isolation.REPEATABLE_READ) public String statement(UUID user,UUID account,LocalDate from,LocalDate to){if(from==null||to==null||from.isAfter(to)||java.time.temporal.ChronoUnit.DAYS.between(from,to)>366)throw bad("INVALID_DATE_RANGE","Choose an inclusive date range of at most 367 days.");if(account!=null)accounts.get(user,account);var rows=repo.statement(user,account,from,to);if(rows.size()>10000)throw new BankException(413,"EXPORT_TOO_LARGE","Narrow the date range; exports support up to 10,000 rows.");StringBuilder csv=new StringBuilder("Transaction ID,Account,Date,Name,Type,Category,Amount USD,Note,Reference\r\n");for(var row:rows){String reference=String.valueOf(row.get("operation_id")!=null?row.get("operation_id"):row.get("peer_payment_id")!=null?row.get("peer_payment_id"):row.get("transfer_id")!=null?row.get("transfer_id"):"");csv.append(String.join(",",csvCell(row.get("id")),csvCell(row.get("account_name")),csvCell(row.get("posted_date")),csvCell(row.get("name")),csvCell(row.get("kind")),csvCell(row.get("category")),((BigDecimal)row.get("amount")).toPlainString(),csvCell(row.get("note")),csvCell(reference))).append("\r\n");}return csv.toString();}
 public static String csvCell(Object value){String s=value==null?"":value.toString();String trimmed=s.stripLeading();if(!trimmed.isEmpty()&&"=+-@\t\r".indexOf(trimmed.charAt(0))>=0)s="'"+s;return "\""+s.replace("\"","\"\"")+"\"";}
}
